    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  },{threshold:.14, rootMargin:'0px 0px -40px 0px'});
  document.querySelectorAll('[data-io]').forEach(function(el){ io.observe(el); });

  /* stagger the ledger cards */
  document.querySelectorAll('.card-wrap').forEach(function(w,i){
    w.style.setProperty('--d', (i % 4) * 90 + 'ms');
  });

  /* ---------- scramble-decode headings ---------- */
  function scramble(el){
    var final = el.textContent;
    var chars = 'ABGKLMNRT§&✦*#—';
    var f = 0, total = 26;
    (function tick(){
      f++;
      var done = Math.floor((f / total) * final.length);
      var out = final.slice(0, done);
      for(var i = done; i < final.length; i++){
        out += final[i] === ' ' ? ' ' : chars[Math.floor(Math.random() * chars.length)];
      }
      el.textContent = out;
      if(f < total) requestAnimationFrame(tick); else el.textContent = final;
    })();
  }
  if(!reduced){
    var sio = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ scramble(e.target); sio.unobserve(e.target); }
      });
    },{threshold:.4});
    document.querySelectorAll('[data-scramble]').forEach(function(el){ sio.observe(el); });
  }

  /* ---------- index flash ---------- */
  document.querySelectorAll('.idx').forEach(function(a){
    a.addEventListener('click', function(){
      var t = document.querySelector(a.getAttribute('href'));
      if(!t) return;
      setTimeout(function(){
        t.classList.remove('flash'); void t.offsetWidth;
        t.classList.add('flash');
        setTimeout(function(){ t.classList.remove('flash'); }, 1300);
      }, 450);
    });
  });

  /* ---------- compose your own bill ---------- */
  var form  = document.getElementById('bill-form');
  var out   = document.getElementById('compose-out');
  var verse = document.getElementById('draft-verse');
  var gen   = 0;

  form.addEventListener('submit', function(e){
    e.preventDefault();
    var rawName = document.getElementById('f-name').value.trim();
    var trade   = document.getElementById('f-trade').value.trim().toLowerCase() || 'bill-collector';
    var name    = rawName ? rawName.replace(/^\w/, function(c){ return c.toUpperCase(); }) : 'Bill';
    var lines = [
      'There once was ' + name + ', the ' + trade + ',',
      'A ' + trade + ' of a very fine grade;',
      'This verse is three lines set —',
      "I bet the next two, you'll",
      'Supply, dear reader, and be paid.'
    ];

    out.hidden = false;
    verse.innerHTML = '';
    verse.classList.remove('in');
    var stamp = out.querySelector('.draft-stamp');
    stamp.classList.remove('pulse'); void stamp.offsetWidth; stamp.classList.add('pulse');
    var my = ++gen;

    if(reduced){
      lines.forEach(function(t,i){
        verse.insertAdjacentHTML('beforeend',
          '<span class="vline" style="--i:' + i + '"><span>' + t + '</span></span>');
      });
      verse.classList.add('in');
      return;
    }

    var li = 0;
    function addLine(){
      if(my !== gen) return;
      if(li >= lines.length) return;
      var o = document.createElement('span');
      o.className = 'vline';
      o.style.setProperty('--i', li);
      var s = document.createElement('span');
      o.appendChild(s);
      verse.appendChild(o);
      verse.classList.add('in');
      var c = 0, text = lines[li];
      var t = setInterval(function(){
        if(my !== gen){ clearInterval(t); return; }
        s.textContent = text.slice(0, ++c);
        if(c >= text.length){
          clearInterval(t);
          li++;
          setTimeout(addLine, 140);
        }
      }, 24);
    }
    addLine();
  });
})();
</script>
</body>
